以下是C语言的极简实操示例：
```c
// 定义结构体类型
struct Student {
    int id;
    char name[20];
};
int main() {
    struct Student stu = {2024, "小明"}; // 定义结构体变量，存实际数据
    struct Student *p = &stu; // 定义结构体指针，存stu的内存地址
    // 两种等价方式访问成员，输出结果：学号：2024，姓名：小明
    printf("学号：%d，姓名：%s", (*p).id, p->name);
    return 0;
}
```
